const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const contexts={norte:{name:'Norte Construcción',projects:[['torre','Torre Norte',['Instalaciones eléctricas','Prevención']]],jobs:[['risk','Protección colectiva sin confirmar','J. Martín','Hoy · 12:30','2','INC-248'],['amber','Pedido de cable con recepción incompleta','Oficina técnica','Hoy · 16:00','1','INC-241'],['info','Checklist de seguridad pendiente','Marta Sáez','Hoy · 13:30','4','checklists']],memory:'Procedimiento LOG-04 · Torre Norte · confianza 92%.',nexo:'86 documentos internos recuperables para Torre Norte.'},atlas:{name:'Atlas Servicios',projects:[['sur','Centro Logístico Sur',['Logística','Prevención']]],jobs:[['amber','Recepción de material por validar','Lucía Campos','Hoy · 15:00','1','INC-241'],['info','Plano de muelle con revisión pendiente','Almacén','Mañana · 09:00','3','plans'],['info','Checklist de recepción pendiente','Lucía Campos','Mañana · 10:00','2','checklists']],memory:'No hay memoria confirmada para este alcance simulado.',nexo:'Catálogo disponible; sin resultados recuperados para este alcance.'}};
const incidents=[['INC-248','risk','critical','Crítica','Protección colectiva incompleta','J. Martín','Hoy · 12:30','2'],['INC-241','amber','review','Revisión','Pedido de cable sin albarán','Oficina técnica','Hoy · 16:00','1']];const planMarks=[['Protección colectiva','risk','J. Martín','Hoy · 12:30','2','INC-248'],['Entrega de cable','amber','Oficina técnica','Hoy · 16:00','1','INC-241'],['Cuadro C-2','info','Marta Sáez','Hoy · 13:30','4','checklists']];let selected=incidents[0];
function icons(){window.lucide?.createIcons()}function toast(m){$('#toast').textContent=m;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2200)}function go(v,id){if(id){selected=incidents.find(x=>x[0]===id)||selected;rows()}$$('.view').forEach(x=>x.classList.toggle('active',x.id===v));$$('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===v));icons()}function open(t){go(t.startsWith('INC-')?'incidents':t,t.startsWith('INC-')?t:null)}function render(){let c=contexts[$('#company').value],p=c.projects[0];$('#project').innerHTML=c.projects.map(x=>`<option>${x[1]}</option>`).join('');$('#department').innerHTML=p[2].map(x=>`<option>${x}</option>`).join('');$('#scopeNote').innerHTML=`Datos simulados: ${c.name} · ${p[1]} · ${$('#department').value}.`;$('#attention').innerHTML=c.jobs.map(x=>`<article class="attention-item" style="--tone:var(--${x[0]})"><div><h2>${x[1]}</h2><p>Excepción del alcance simulado.</p></div><span>Responsable<b>${x[2]}</b></span><span>Vencimiento<b>${x[3]}</b></span><span>Evidencia<b>${x[4]} registros</b></span><button class="button" data-open="${x[5]}">Abrir</button></article>`).join('');$('#workInbox').innerHTML=c.jobs.map(x=>`<article class="panel"><span class="severity ${x[0]}">${x[5]==='plans'?'Plano relevante':'Trabajo pendiente'}</span><h2>${x[1]}</h2><p>${x[2]} · ${x[3]} · ${x[4]} evidencias</p><button class="button" data-open="${x[5]}">Abrir</button></article>`).join('');$('#calendarItems').innerHTML=c.jobs.slice(0,2).map(x=>`<article><h2>${x[1]}</h2><p>${x[2]} · ${x[3]} · evidencia ${x[4]}</p></article>`).join('');$('#panoramaText').textContent=`Resumen simulado de ${p[1]}.`;$('#panoramaMetrics').textContent=c.name==='norte'?'Avance 72% · 3 excepciones abiertas.':'Avance 48% · 2 seguimientos abiertos.';$('#checklistText').textContent=c.jobs.find(x=>x[5]==='checklists')?.[1]||'No hay checklist pendiente.';$('#chatTitle').textContent=c.jobs[0][1];$('#chatText').textContent=`Respuesta basada únicamente en ${p[1]} y sus registros simulados.`;$('#memoryText').textContent=c.memory;$('#nexoText').textContent=c.nexo;$('#planMarks').innerHTML=planMarks.map((x,i)=>`<button class="tag ${x[1]}" style="${i===0?'top:25%;left:20%':i===1?'top:55%;right:20%':'bottom:22%;left:45%'}" data-mark="${i}">${x[0]}</button>`).join('');$$('[data-open]').forEach(x=>x.onclick=()=>open(x.dataset.open));$$('[data-mark]').forEach(x=>x.onclick=()=>{let m=planMarks[x.dataset.mark];$('#planDetail').innerHTML=`<b>${m[0]}</b><p>Tipo: ${m[1]} · Responsable: ${m[2]} · Vence: ${m[3]} · Evidencia: ${m[4]} registros simulados.</p><button class="button" data-open="${m[5]}">Abrir trabajo relacionado</button>`;$('#planDetail button').onclick=()=>open(m[5])});icons()}function rows(){let r=incidents.filter(x=>$('#status').value==='all'||x[2]===$('#status').value);$('#rows').innerHTML=r.map(x=>`<tr class="${x===selected?'selected':''}" data-id="${x[0]}"><td class="severity ${x[1]}">${x[3]}</td><td>${x[4]}</td><td>${x[5]}</td><td>${x[6]}</td><td>${x[7]}</td></tr>`).join('')||'<tr><td colspan="5">No hay incidencias en este alcance simulado.</td></tr>';$('#detail').innerHTML=`<h2>${selected[4]}</h2><p>Responsable: ${selected[5]} · vence ${selected[6]} · ${selected[7]} evidencias simuladas.</p>`;$$('[data-id]').forEach(x=>x.onclick=()=>{selected=incidents.find(y=>y[0]===x.dataset.id);rows()})}
$$('[data-view]').forEach(x=>x.onclick=()=>go(x.dataset.view));$('#company').onchange=render;$('#project').onchange=render;$('#department').onchange=render;$('#status').onchange=rows;$('#clear').onclick=()=>{$('#status').value='all';rows()};$('#offline').onclick=()=>{let o=$('#syncStatus');o.textContent=o.textContent.includes('Offline')?'Sincronizado':'Offline simulado · última información local';toast(o.textContent)};$('#theme').onclick=()=>document.body.classList.toggle('light');$('#scan').onclick=()=>toast('Escanear es una acción visual simulada; no usa cámara ni datos reales.');$('#snooze').onclick=()=>{ $('#snooze').textContent='Pospuesto 1 h';$('#snooze').disabled=true;toast('Recordatorio pospuesto (simulado).')};$$('[data-state]').forEach(x=>x.onclick=()=>{$('#state').hidden=false;$('#state').innerHTML=x.dataset.state==='loading'?'<div class="panel">Cargando datos simulados…</div>':`<div class="panel">${x.dataset.state==='empty'?'No hay datos para este alcance.':'No se pudo actualizar; se conserva la última lectura simulada.'}</div>`});render();rows();icons();
